import{_ as i,c as a,o as e,a2 as t}from"./chunks/framework.PGES7OoM.js";const g=JSON.parse('{"title":"getActivityPage","description":"Query the complete local private history, keeping page membership stable as new entries arrive.","frontmatter":{"editLink":false,"rawMarkdown":"# getActivityPage\\n\\nQuery the complete local private history, keeping page membership stable as new entries arrive.\\n\\n## Import\\n\\n```ts\\nimport { getActivityPage } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await getActivityPage({ config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction getActivityPage(parameters?: GetActivityPageParameters): Promise<ActivityPage>\\n```\\n\\n## Returns\\n\\n`Promise<ActivityPage>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nThe account whose history is paged. Defaults to the active account.\\n\\n```ts\\nconst result = await getActivityPage({\\n  accountId, // [!code focus]\\n});\\n```\\n\\n### `filters`\\n\\n- **Type:** `ActivityFilters`\\n- **Required:** no\\n\\nRestrict the page by free-text query, kinds, network slug or vault token id.\\n\\n```ts\\nconst result = await getActivityPage({\\n  filters, // [!code focus]\\n});\\n```\\n\\n### `cursor`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nA cursor from a previous page. Reusing a page\'s own `cursor` refreshes statuses without changing membership.\\n\\n```ts\\nconst result = await getActivityPage({\\n  cursor, // [!code focus]\\n});\\n```\\n\\n### `pageSize`\\n\\n- **Type:** `number`\\n- **Required:** no\\n\\nThe number of items per page.\\n\\n```ts\\nconst result = await getActivityPage({\\n  pageSize, // [!code focus]\\n});\\n```\\n\\n### `seenIds`\\n\\n- **Type:** `readonly string[]`\\n- **Required:** no\\n\\nOptional legacy host acknowledgements. SDK storage is restored automatically.\\n\\n```ts\\nconst result = await getActivityPage({\\n  seenIds, // [!code focus]\\n});\\n```\\n\\n### `signal`\\n\\n- **Type:** `AbortSignal`\\n- **Required:** no\\n\\nAborts the read.\\n\\n```ts\\nconst result = await getActivityPage({\\n  signal, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await getActivityPage({\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/views/getActivityPage.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/views/getActivityPage.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/views/getActivityPage.md","rawMarkdownTitle":"getActivityPage","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/views/getActivityPage.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"views","action":"getActivityPage"},"relativePath":"sdk/actions/views/getActivityPage.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/views/getActivityPage.md"};function r(l,s,h,o,p,c){return e(),a("div",null,[...s[0]||(s[0]=[t("",46)])])}const k=i(n,[["render",r]]);export{g as __pageData,k as default};
